# Batch B — 50 State Quarters (Washington) Mint Tier-A claims for Agent Builder pilot (26 Oct 2026).
# Figures from U.S. Mint circulating production Excels (Wayback) + Mint program pages. Report-only.
ROWS = [
 dict(row=1, slot='state_quarters#program_scope', ours='1999-2008 5/year admission order',
      claim='The United States Mint 50 State Quarters Program was a 10-year initiative launched in 1999 that honored each of the 50 states. The Mint issued five new quarters each year in the order that the states ratified the Constitution or were admitted into the Union.',
      opposite='The 50 State Quarters Program issued ten new quarters each year from 1995 through 2005 in alphabetical order by state name.',
      queries=['50 State Quarters Program 10-year initiative 1999 five new quarters each year order ratified Constitution',
               'United States Mint 50 State Quarters Program launched 1999']),
 dict(row=2, slot='state_quarters#obverse_inscriptions', ours='Washington obverse; legends moved',
      claim='On 50 State Quarters, the reverse features a design related to that state, while the obverse shows the familiar portrait of George Washington used on the quarter since 1932. The inscriptions UNITED STATES OF AMERICA, QUARTER DOLLAR, LIBERTY, and IN GOD WE TRUST appear on the obverse to accommodate the state designs.',
      opposite='On 50 State Quarters, UNITED STATES OF AMERICA and QUARTER DOLLAR remain on the reverse under the state design, and Washington was removed from the obverse.',
      queries=['50 State Quarters obverse George Washington inscriptions UNITED STATES OF AMERICA QUARTER DOLLAR LIBERTY IN GOD WE TRUST',
               '50 State Quarters Program reverse state design obverse Washington']),
 dict(row=3, slot='state_quarters#production_window', ours='~10 weeks never again',
      claim='Under the 50 State Quarters Program, each quarter was produced for about 10 weeks and will never be produced again.',
      opposite='Each 50 State Quarter design remained in continuous production for the entire calendar year and was reissued annually.',
      queries=['50 State Quarters each quarter produced about 10 weeks never produced again',
               'United States Mint 50 State Quarters Program production period 10 weeks']),
 dict(row=4, slot='state_quarters_1999#Delaware', ours='DE D/P mintages',
      claim='The 1999 Delaware 50 State Quarter circulating production was 401,424,000 at Denver and 373,400,000 at Philadelphia, for a total of 774,824,000 coins.',
      opposite='The 1999 Delaware State Quarter had a circulating mintage under 50 million coins combined.',
      queries=['1999 Delaware 50 State Quarters Program Production Denver 401,424,000 Philadelphia 373,400,000',
               '1999 Delaware State Quarter circulating production Denver Philadelphia']),
 dict(row=5, slot='state_quarters_1999#Connecticut', ours='CT highest 1999',
      claim='Among the 1999 50 State Quarters, Connecticut had the highest circulating total: 657,880,000 Denver and 688,744,000 Philadelphia, for a combined 1,346,624,000 coins. The 1999 program-year grand total was 4,430,940,000 coins.',
      opposite='Among 1999 State Quarters, New Jersey had the highest circulating mintage and the 1999 year total was under one billion.',
      queries=['1999 Connecticut 50 State Quarters Program Production Denver 657,880,000 Philadelphia 688,744,000 Grand Total 4,430,940,000',
               '1999 50 State Quarters Connecticut circulating production Grand Total']),
 dict(row=6, slot='state_quarters_2000#Virginia', ours='VA highest series',
      claim='The 2000 Virginia 50 State Quarter circulating production was 651,616,000 at Denver and 943,000,000 at Philadelphia, for a total of 1,594,616,000 coins.',
      opposite='The 2000 Virginia State Quarter circulating total was under 200 million coins.',
      queries=['2000 Virginia 50 State Quarters Program Production Denver 651,616,000 Philadelphia 943,000,000',
               '2000 Virginia State Quarter circulating production Denver Philadelphia Total']),
 dict(row=7, slot='state_quarters#facilities_PD', ours='P and D circulating',
      claim='Circulating 50 State Quarters production figures are reported for the United States Mints at Denver and Philadelphia. Coins minted for numismatic bags, rolls, and boxes are produced in the circulating departments of those facilities and may be shown in circulating totals.',
      opposite='All circulating 50 State Quarters for commerce were struck exclusively at the San Francisco Mint with an S mint mark.',
      queries=['50 State Quarters Program Production Denver Philadelphia circulating departments numismatic bags rolls',
               'United States Mint circulating coins production Denver Philadelphia 50 State Quarters']),
 dict(row=8, slot='state_quarters_2008#order', ours='OK NM AZ AK HI 2008',
      claim='The 2008 50 State Quarters designs were Oklahoma, New Mexico, Arizona, Alaska, and Hawaii — the final year of the 50 State Quarters Program.',
      opposite='The 2008 State Quarters designs were Delaware, Pennsylvania, New Jersey, Georgia, and Connecticut.',
      queries=['2008 50 State Quarters Oklahoma New Mexico Arizona Alaska Hawaii',
               '50 State Quarters Program 2008 coins reverse Oklahoma Hawaii']),
 dict(row=9, slot='state_quarters_2008#Oklahoma', ours='OK mintages lowest-class',
      claim='The 2008 Oklahoma 50 State Quarter circulating production was 194,600,000 at Denver and 222,000,000 at Philadelphia, for a total of 416,600,000 coins.',
      opposite='The 2008 Oklahoma State Quarter circulating total exceeded one billion coins.',
      queries=['2008 Oklahoma 50 State Quarters Program Production Denver 194,600,000 Philadelphia 222,000,000 Total 416,600,000',
               '2008 Oklahoma State Quarter circulating production Denver Philadelphia']),
 dict(row=10, slot='state_quarters_1999#order', ours='DE PA NJ GA CT',
      claim='The 1999 50 State Quarters designs were Delaware, Pennsylvania, New Jersey, Georgia, and Connecticut.',
      opposite='The 1999 State Quarters designs were California, Oregon, Kansas, Minnesota, and West Virginia.',
      queries=['1999 50 State Quarters Delaware Pennsylvania New Jersey Georgia Connecticut',
               '50 State Quarters Program 1999 coins reverse Delaware Connecticut']),
 dict(row=11, slot='state_quarters_2002#Mississippi', ours='MS mintages',
      claim='The 2002 Mississippi 50 State Quarter circulating production was 289,600,000 at Denver and 290,000,000 at Philadelphia, for a total of 579,600,000 coins.',
      opposite='The 2002 Mississippi State Quarter circulating total exceeded two billion coins.',
      queries=['2002 Mississippi 50 State Quarters Program Production Denver 289,600,000 Philadelphia 290,000,000',
               '2002 Mississippi State Quarter circulating production Denver Philadelphia']),
 dict(row=12, slot='state_quarters#2009_territories_followon', ours='2009 DC+territories separate',
      claim='In 2009, after the 50 State Quarters Program ended in 2008, the United States Mint issued six more quarter designs for Washington, DC and the five U.S. territories as part of the District of Columbia and U.S. Territories Quarters Program.',
      opposite='Washington, DC and the U.S. territories were included as the final six designs inside the original 1999-2008 50 State Quarters Program.',
      queries=['2009 District of Columbia and U.S. Territories Quarters Program after 50 State Quarters',
               '50 State Quarters Program 2009 Washington DC territories six designs']),
]
assert [r['row'] for r in ROWS] == list(range(1, 13))

